const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const dcPoint = ee.Geometry.Point([-77.0369, 38.9072]); // Washington D.C.
    const startDate = '2018-01-01';
    const endDate = '2018-12-31';

    // 2. Data Acquisition & Check
    // Using PRISM dataset, which is high-resolution for the CONUS.
    // Band 'ppt' is precipitation in millimeters.
    let precipCollection = ee.ImageCollection('OREGONSTATE/PRISM/AN81d')
        .filterBounds(dcPoint)
        .filterDate(startDate, endDate)
        .select('ppt');

    const collectionSize = precipCollection.size().getInfo();
    if (collectionSize === 0) {
        console.log("Evidence: No PRISM images found for Washington D.C. in 2018.");
        console.log("C1");
        return;
    }
    console.log(`Evidence: Found ${collectionSize} daily precipitation images for 2018.`);

    // 3. Processing: Sum the precipitation over the year
    const totalPrecipitationImage = precipCollection.sum();

    // 4. Calculation: Reduce the region to get a single value
    const precipStats = totalPrecipitationImage.reduceRegion({
        reducer: ee.Reducer.first(),
        geometry: dcPoint,
        scale: 4000, // PRISM native resolution is ~4km
        maxPixels: 1e9
    });

    const totalPrecipMM = precipStats.get('ppt').getInfo();

    // 5. Validation & Final Answer
    if (totalPrecipMM === null || totalPrecipMM === undefined) {
        console.log("Evidence: Calculation resulted in a null value. Could not extract precipitation data.");
        console.log("C3");
        return;
    }

    // Convert millimeters to inches (1 inch = 25.4 mm)
    const totalPrecipInches = totalPrecipMM / 25.4;
    const thresholdInches = 50.0;

    console.log(`Evidence: Total calculated rainfall (mm): ${totalPrecipMM.toFixed(2)}`);
    console.log(`Evidence: Total calculated rainfall (inches): ${totalPrecipInches.toFixed(2)}`);
    console.log(`Evidence: Required threshold (inches): ${thresholdInches}`);

    if (totalPrecipInches >= thresholdInches) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
